insert into public.library_articles (id, section, title, meta, body, is_free, sort_order) values
('breeds-0', 'breeds', 'Thoroughbred', 'England · 15.2–17 hh · racing, eventing, jumping', 'Bred for racing from three Arabian-type foundation stallions in the 17th–18th centuries. Athletic, fast and sensitive ("hot-blooded"), with a fine coat and long legs. Many retrain from racing into eventing, show jumping and riding-club work.', true, 0),
('breeds-1', 'breeds', 'Welsh Pony and Cob', 'Wales · Sections A–D · all-round', 'Four sections share one stud book: Section A (Welsh Mountain Pony, up to 12 hh), B (riding pony, up to 13.2 hh), C (pony of cob type, up to 13.2 hh) and D (Welsh Cob, over 13.2 hh). Hardy, clever and brave; a favourite riding-school mount.', true, 1),
('breeds-2', 'breeds', 'Arabian', 'Arabian Peninsula · 14.1–15.1 hh · endurance', 'One of the oldest breeds, with a dished face, large eyes and high tail carriage. Known for stamina, so it dominates endurance riding. Has influenced most modern light breeds.', false, 2),
('breeds-3', 'breeds', 'Irish Sport Horse', 'Ireland · 15.2–17 hh · eventing, jumping', 'Traditionally an Irish Draught crossed with a Thoroughbred. Sound, sensible and bold across country; widely seen in eventing and show jumping at every level.', false, 3),
('breeds-4', 'breeds', 'Dutch Warmblood (KWPN)', 'Netherlands · 16–17 hh · dressage, jumping', 'A sport horse selected for movement and jumping ability. Usually split into dressage and jumping lines. Elastic paces and a trainable temperament.', false, 4),
('breeds-5', 'breeds', 'Hanoverian', 'Germany · 15.3–17.2 hh · dressage, jumping', 'One of the most successful warmbloods in Olympic sport. Strong back and hindquarters, balanced paces and a willing temperament.', false, 5),
('breeds-6', 'breeds', 'Connemara Pony', 'Ireland · 12.2–14.2 hh · jumping, all-round', 'Hardy native pony from the west of Ireland, often grey or dun. Famous for jumping ability and good sense; suits both children and lighter adults.', false, 6),
('breeds-7', 'breeds', 'Andalusian (PRE)', 'Spain · 15–16.2 hh · classical dressage', 'Pura Raza Española. Powerful, compact and agile, with a long thick mane; most are grey. Prized for collection and classical high-school work.', false, 7),
('breeds-8', 'breeds', 'Friesian', 'Netherlands · 15–17 hh · dressage, driving', 'Almost always black, with feathered lower legs and an upright neck. High-stepping trot; popular for driving and dressage.', false, 8),
('breeds-9', 'breeds', 'American Quarter Horse', 'USA · 14–16 hh · western, ranch', 'Named for sprinting a quarter mile. Muscular hindquarters, calm temperament and quick turns; the core breed of western riding.', false, 9),
('breeds-10', 'breeds', 'Appaloosa', 'USA · 14–16 hh · western, trail', 'Developed by the Nez Perce people. Known for leopard-complex spotted coats, striped hooves and mottled skin.', false, 10),
('breeds-11', 'breeds', 'Shetland Pony', 'Scotland · up to 42 in (about 10.2 hh) · children, driving', 'Small but very strong for its size, with a thick double coat. Clever and sometimes cheeky; often a child''s first pony.', false, 11),
('breeds-12', 'breeds', 'Clydesdale', 'Scotland · 16–18 hh · draught', 'Heavy horse bred for farm and haulage work, often bay with a white face and heavily feathered white legs. Gentle and willing.', false, 12),
('colours-0', 'colours', 'Bay', 'Base colour', 'Brown body with black "points": black mane, tail and lower legs. Shades run from light bay to dark bay, which can look almost black.', true, 0),
('colours-1', 'colours', 'Chestnut', 'Base colour', 'Red-brown coat with a mane and tail the same colour or lighter; never black points. Ranges from pale "sorrel" to dark liver chestnut.', true, 1),
('colours-2', 'colours', 'Black', 'Base colour', 'Entirely black, including the muzzle and flanks. Many "blacks" that fade brown in the sun are true blacks; brown muzzles suggest a dark bay.', false, 2),
('colours-3', 'colours', 'Grey', 'Modifier', 'Born dark and turns lighter with age, often through "dappled grey" to almost white. A grey horse has dark skin, unlike a true white.', false, 3),
('colours-4', 'colours', 'Palomino', 'Dilution', 'Gold coat with a white or flaxen mane and tail. Caused by one cream gene on a chestnut base.', false, 4),
('colours-5', 'colours', 'Buckskin', 'Dilution', 'Tan or gold body with black points. One cream gene on a bay base.', false, 5),
('colours-6', 'colours', 'Dun', 'Dilution', 'Diluted body colour with "primitive markings": a dark dorsal stripe along the back, and often leg barring.', false, 6),
('colours-7', 'colours', 'Roan', 'Pattern', 'White hairs evenly mixed through the body while the head and legs stay darker. Called blue, red or bay roan by base colour.', false, 7),
('colours-8', 'colours', 'Piebald and skewbald', 'Pattern', 'Large patches of white with another colour. In British usage piebald is black and white, skewbald is white with any other colour; in the US both are "pinto".', false, 8),
('colours-9', 'colours', 'Leopard and spotted', 'Pattern', 'Leopard-complex patterns: spots over a white coat (leopard), a white blanket over the hips, or scattered spots. Linked with Appaloosa and Knabstrupper horses.', false, 9),
('colours-10', 'colours', 'Face markings', 'Markings', 'Star: white on the forehead. Stripe: narrow white down the face. Blaze: broad white down the face. Snip: white between the nostrils. Bald or white face: white covering most of the face.', false, 10),
('colours-11', 'colours', 'Leg markings', 'Markings', 'Coronet: white just above the hoof. Sock: white to the fetlock or a little above. Stocking: white up to the knee or hock. Ermine marks are dark spots inside white.', false, 11),
('terms-0', 'terms', 'Aids', 'Riding', 'The signals a rider uses to communicate: natural aids are the seat, legs, hands and voice; artificial aids include the whip and spurs.', true, 0),
('terms-1', 'terms', 'Half-halt', 'Riding', 'A brief, coordinated use of seat, leg and rein that rebalances the horse and prepares it for a change, without actually stopping.', true, 1),
('terms-2', 'terms', 'Diagonal', 'Riding', 'In rising trot, rise as the outside foreleg goes forward. Change diagonal by sitting one extra beat when you change rein.', false, 2),
('terms-3', 'terms', 'Canter lead', 'Riding', 'On a circle the inside foreleg should reach furthest forward ("leading"). Wrong lead = the outside leg leads unasked.', false, 3),
('terms-4', 'terms', 'Contact', 'Riding', 'The steady, elastic connection between the rider''s hands and the horse''s mouth through the reins.', false, 4),
('terms-5', 'terms', 'Impulsion', 'Dressage', 'Controlled energy from the hindquarters, carried forward through a swinging back. Not the same as speed.', false, 5),
('terms-6', 'terms', 'Collection', 'Dressage', 'Shortened, more elevated steps with the hindquarters carrying more weight. Its opposite in the paces is extension.', false, 6),
('terms-7', 'terms', 'Outline', 'Dressage', 'The horse''s overall shape: working "on the bit" means accepting the contact, with the poll the highest point and the face near vertical.', false, 7),
('terms-8', 'terms', 'Leg-yield', 'Dressage', 'A lateral movement where the horse moves forward and sideways away from the rider''s leg, body nearly straight, slightly bent away from the direction of travel.', false, 8),
('terms-9', 'terms', 'Shoulder-in', 'Dressage', 'A three-track lateral movement with the shoulders brought in off the track and the horse bent around the inside leg.', false, 9),
('terms-10', 'terms', 'Counter-canter', 'Dressage', 'Cantering deliberately on the outside lead, for example on a shallow loop. A test of balance and straightness.', false, 10),
('terms-11', 'terms', 'Flying change', 'Dressage', 'Changing canter lead in the moment of suspension, without returning to trot or walk.', false, 11),
('terms-12', 'terms', 'Collective marks', 'Dressage', 'Marks at the end of a test score overall qualities, such as paces, the rider''s position and the harmony between horse and rider.', false, 12),
('terms-13', 'terms', 'Vertical', 'Jumping', 'A fence with poles set one above the other in a single plane, with no spread.', false, 13),
('terms-14', 'terms', 'Oxer', 'Jumping', 'A spread fence of two (or more) elements. Ascending oxers have a lower front rail; square oxers have both rails level.', false, 14),
('terms-15', 'terms', 'Related distance', 'Jumping', 'Two fences set a fixed number of strides apart, usually 3 to 5. Rhythm on the approach decides how it rides.', false, 15),
('terms-16', 'terms', 'Combination', 'Jumping', 'Two or three fences with one or two strides between them, numbered as one fence (e.g. 5a, 5b).', false, 16),
('terms-17', 'terms', 'Grid', 'Jumping', 'A line of poles and small fences at set distances, used to teach rhythm, technique and rider position.', false, 17),
('terms-18', 'terms', 'Faults', 'Jumping', 'Under common rules a knockdown or first refusal costs 4 faults. Time faults are added for going over the time allowed. Check your own federation''s rules.', false, 18),
('terms-19', 'terms', 'Clear round', 'Jumping', 'A round with no jumping or time faults.', false, 19),
('terms-20', 'terms', 'Jump-off', 'Jumping', 'A shortened, timed second round for riders tied on faults; fastest clear usually wins.', false, 20),
('terms-21', 'terms', 'Bascule', 'Jumping', 'The arc a horse makes over a fence, rounding its back and lowering its head and neck.', false, 21),
('terms-22', 'terms', 'Near side and off side', 'Stable', 'The horse''s left side is the near side, its right the off side. Horses are traditionally led and mounted from the near side.', false, 22),
('terms-23', 'terms', 'Hands (hh)', 'Stable', 'Horse height is measured to the withers in hands; one hand is 4 inches (10.16 cm). 15.2 hh means 15 hands and 2 inches.', false, 23),
('terms-24', 'terms', 'Tacking up', 'Stable', 'Putting on the saddle, bridle and any boots or other equipment before riding.', false, 24),
('tack-0', 'tack', 'Riding hat', 'Rider safety', 'Wear a hat to a current safety standard every time you ride, fastened snugly. Replace it after any fall or hard knock, even if it looks fine.', true, 0),
('tack-1', 'tack', 'Body protector', 'Rider safety', 'A padded vest that reduces injury in falls; required for cross-country in most competitions. Fit is by chest, waist and length measurements.', true, 1),
('tack-2', 'tack', 'Riding boots and gloves', 'Rider safety', 'Boots need a small heel so the foot cannot slide through the stirrup. Gloves improve grip on the reins in rain or with a sweaty horse.', false, 2),
('tack-3', 'tack', 'General-purpose saddle', 'Saddles', 'A mid-length flap and moderate knee rolls for flatwork, hacking and small jumps. Ideal for lessons. Must clear the withers and spine and match the horse''s shape.', false, 3),
('tack-4', 'tack', 'Dressage saddle', 'Saddles', 'A deep seat and long, straight flap for a long leg position. Puts the rider''s leg directly under the hip.', false, 4),
('tack-5', 'tack', 'Jumping saddle', 'Saddles', 'A forward-cut flap and bigger knee blocks to support the shorter stirrup and the jumping position.', false, 5),
('tack-6', 'tack', 'Snaffle bridle', 'Bridles and bits', 'The standard bridle: headpiece, browband, cheekpieces, noseband and a single snaffle bit. You should fit two fingers under the throatlash and one under a cavesson noseband.', false, 6),
('tack-7', 'tack', 'Snaffle bits', 'Bridles and bits', 'Act on the corners of the mouth, tongue and bars without leverage. Common types: loose-ring, eggbutt and D-ring. A correctly sized bit just wrinkles the corners of the lips.', false, 7),
('tack-8', 'tack', 'Girth', 'Saddles', 'Holds the saddle in place. Check it before mounting and again after a few minutes of riding, as many horses relax and the girth loosens.', false, 8),
('tack-9', 'tack', 'Saddle pad (numnah)', 'Saddles', 'Absorbs sweat and protects the saddle. Pull it well up into the saddle''s gullet so it doesn''t press on the withers.', false, 9),
('tack-10', 'tack', 'Martingale', 'Training aids', 'A running martingale stops the horse lifting its head too high to be controlled. Fit: the rings should reach the withers when held up.', false, 10),
('tack-11', 'tack', 'Brushing and tendon boots', 'Leg protection', 'Brushing boots protect against knocks from the opposite leg; tendon boots guard the back of the front legs when jumping. Fit them snugly, straps pointing backward.', false, 11),
('tack-12', 'tack', 'Rugs', 'Stable', 'Turnout rugs are waterproof; stable rugs are not. Fit is measured from the centre of the chest to the tail. Rug to the horse''s needs, not the rider''s comfort.', false, 12),
('care-0', 'care', 'Daily health check', 'Every day', 'Look for: bright eyes and alert ears, normal appetite and droppings, even weight on all four legs, no new heat or swelling in the legs, and no cuts. Learn what is normal for your horse.', true, 0),
('care-1', 'care', 'Normal vital signs', 'Adult horse at rest', 'Temperature 37.5–38.5 °C (99.5–101.3 °F). Heart rate 28–44 beats per minute. Breathing 10–24 breaths per minute. Call a vet if they are well outside these and the horse is resting.', true, 1),
('care-2', 'care', 'Grooming', 'Before and after riding', 'Curry comb in circles to lift dirt, body brush to clean, then a soft cloth. Pick out feet before and after every ride. Check the saddle and girth area for rubs.', false, 2),
('care-3', 'care', 'Feeding basics', 'Nutrition', 'Feed plenty of forage (grass, hay or haylage) as the base of the diet; horses need to chew for many hours a day. Feed little and often, change feeds gradually, and keep clean water available at all times.', false, 3),
('care-4', 'care', 'Hoof care', 'Farrier', 'Pick feet out daily and check shoes for looseness or risen clenches. Most horses see a farrier every 5–8 weeks, shod or barefoot.', false, 4),
('care-5', 'care', 'Teeth', 'Dentist', 'Have teeth checked by a vet or qualified equine dentist at least once a year. Signs of trouble: dropping feed, head tossing, or resisting the bit.', false, 5),
('care-6', 'care', 'Worming', 'Parasites', 'Most yards now use faecal egg counts to decide when to worm, rather than worming on a fixed calendar. Ask your vet for a plan.', false, 6),
('care-7', 'care', 'Vaccinations', 'Vet', 'Common vaccines include tetanus and equine influenza; competition rules often require a flu record. Your vet decides the schedule for your country.', false, 7),
('care-8', 'care', 'Colic warning signs', 'Emergency', 'Pawing, looking at or kicking the belly, rolling, sweating, no droppings or a raised heart rate. Colic can be an emergency: call your vet straight away.', false, 8),
('care-9', 'care', 'Lameness signs', 'Vet', 'Head nodding in trot (the head rises when the sore front leg lands), shortened stride, or reluctance to move. Stop riding and get advice.', false, 9),
('lower-leg', 'tips', 'Keep your stirrups and lower leg', 'Position', 'Let your weight drop through your hip, knee and ankle into the heel; don''t push the heel down with force. Ride with the ball of the foot on the stirrup and practise sitting trot and canter without stirrups for short spells.', true, 0),
('position', 'tips', 'Stop getting ahead of the movement', 'Position', 'Keep your shoulders over your hips in the approach. Over a fence, fold from the hip and let the horse close the angle; don''t throw your upper body forward. Grid work at a small height builds this.', true, 1),
('rhythm', 'tips', 'Hold the rhythm', 'Flatwork and jumping', 'Count the beat out loud. Use half-halts on the outside rein when the horse quickens, and a little leg when it slows. A steady rhythm makes distances and transitions come right.', false, 2),
('stride', 'tips', 'Seeing a stride', 'Jumping', 'Work on a consistent canter first. Ride poles on the ground and count strides back from them; the eye follows when the canter stays the same.', false, 3),
('lead', 'tips', 'Getting the correct canter lead', 'Flatwork', 'Ask in a corner or on a circle. Bend slightly to the inside, outside leg back behind the girth, inside leg on the girth, and sit for the transition. A balanced trot before you ask matters most.', false, 4),
('refusals', 'tips', 'After a refusal or run-out', 'Jumping', 'Stay calm, circle away and re-present in a straight line with more leg and a clear focus beyond the fence. Lower the fence if confidence is the issue, for horse or rider.', false, 5),
('confidence', 'tips', 'Building confidence', 'Mindset', 'Set small goals you can reach, breathe out in the approach, and end on a good note. Tell your instructor how you feel; going back a step is progress, not failure.', false, 6),
('contact', 'tips', 'Soft, steady hands', 'Contact', 'Carry your hands, thumbs on top, with a straight line from elbow to bit. Keep elbows soft so they follow the movement, and give and retake the rein to check the horse is carrying itself.', false, 7),
('bend', 'tips', 'Riding accurate circles', 'Flatwork', 'Plan four points of the circle and look ahead to each. Inside leg on the girth for bend, outside rein to control the shoulder. Geometry wins dressage marks.', false, 8),
('transitions', 'tips', 'Smoother transitions', 'Flatwork', 'Prepare with a half-halt two or three strides before, keep your leg on through downward transitions, and ride each transition at a marker so you can measure accuracy.', false, 9)
